/* Tests au D20 : une difficulté explicite, des modificateurs issus du parcours,
   et une probabilité calculée par dénombrement des faces possibles. */
(function(root){const L=root.Life;
function checkModel(s,type,v={}){const p=s.person,bonuses=[],add=(label,value)=>{if(value)bonuses.push({label,value})};let dc=12,k='social',label='Un test de compétence';
if(type==='job'){const sec=L.sectors[v.sector];if(!sec)return null;k=sec.skill;dc=11+(v.level||0)*3+(v.load===3?1:0);label='Entretien : '+v.title;add('Diplôme / qualification',Math.min(2,p.education));add('Expérience dans ce secteur',Math.min(3,Math.floor((p.experience[v.sector]||0)/4)));add('Préparation de l’entretien',Math.floor(p.preparation/3));add('Réseau professionnel',p.network>=50?1:0);add('Réputation',p.reputation>=60?1:0);add('Conjoncture',s.world.phase==='recession'?-2:s.world.phase==='expansion'?1:0)}
else if(type==='promotion'){k=L.sectors[p.career?.sector]?.skill||'management';dc=15+(p.career?.level||0)*2;label='Demande de promotion';add('Ancienneté dans le poste',Math.min(3,Math.floor((p.career?.years||0)/2)));add('Préparation de l’entretien',Math.floor(p.preparation/3));add('Réputation',p.reputation>=50?2:0);add('Conjoncture',s.recession?-2:1)}
else if(type==='date'){k='social';dc=12;label='Faire une rencontre';add('Réseau social',p.network>=40?1:0);add('Stress élevé',p.stress>70?-2:0)}
else if(type==='scholarship'){k='academic';dc=15;label='Dossier de bourse';add('Priorité sociale du dossier',p.wealthTier<.4?3:p.wealthTier<.7?1:0);add('Qualification',Math.min(2,p.education))}
else if(type==='project'){const t=L.templates[v.type];if(!t||!['startup','book','migration','marathon'].includes(v.type))return null;k=t.skill;dc={startup:15,book:16,migration:16,marathon:14}[v.type];label=t.name;add('Préparation du projet',Math.floor((v.quality||0)/2));add('Approche choisie',v.strategy==='safe'?2:v.strategy==='bold'?-1:0);if(v.type==='migration'){add('Langues apprises',Math.min(4,p.languages*2));add('Qualification',Math.min(2,p.education));const dest=L.countries.find(x=>x.code===v.destination);if(dest&&dest.income>L.country(s).income*3){dc+=2;bonuses.push({label:'Destination plus sélective (difficulté +2)',value:0,context:true})}add('Soutien du couple',p.partner&&p.partner.bond>=65?1:0)}if(v.type==='startup'){add('Réseau commercial',p.network>=45?1:0);add('Conjoncture',s.recession?-2:1)}if(v.type==='marathon')add('État de santé',Math.floor((p.health-60)/15))}
else if(type==='whistle'){k='social';dc=15;label='Faire entendre un signalement';add('Crédibilité',Math.floor(p.reputation/25))}else return null;
add(L.skills[k]||'Compétence',Math.floor(L.skill(p,k)/15));const modifier=bonuses.reduce((a,b)=>a+b.value,0);let advantage='normal';if(['job','promotion'].includes(type)&&p.preparation>=6&&p.energy>=45)advantage='advantage';if(p.energy<20||p.stress>88)advantage='disadvantage';const success=n=>n===20||(n!==1&&n+modifier>=dc);let wins=0,total=advantage==='normal'?20:400;if(advantage==='normal'){for(let n=1;n<=20;n++)if(success(n))wins++}else for(let a=1;a<=20;a++)for(let b=1;b<=20;b++)if(success(advantage==='advantage'?Math.max(a,b):Math.min(a,b)))wins++;return{type,label,skill:k,dc,modifier,bonuses,advantage,probability:wins/total,formula:'D20 '+(modifier>=0?'+ ':'− ')+Math.abs(modifier)+' ≥ '+dc}}
function resolve(s,type,v={}){const model=L.checkModel(s,type,v);if(!model)return null;const rolls=[1+Math.floor(L.rand(s)*20)];if(model.advantage!=='normal')rolls.push(1+Math.floor(L.rand(s)*20));const die=model.advantage==='advantage'?Math.max(...rolls):model.advantage==='disadvantage'?Math.min(...rolls):rolls[0],success=die===20||(die!==1&&die+model.modifier>=model.dc);const result={...model,rolls,die,total:die+model.modifier,critical:die===20?'success':die===1?'failure':null,success};s.checkResult=result;if(die===20){s.person.reputation=L.clamp(s.person.reputation+2);s.person.happiness=L.clamp(s.person.happiness+2)}if(die===1)s.person.stress=L.clamp(s.person.stress+3);return result}
L.checkModel=checkModel;L.resolveCheck=resolve;
})(typeof window!=='undefined'?window:globalThis);
